def excluir(d): return any(re.search(p,d) for p in EXCLUIR)
def ajuste(d,cat,sub):
    for p,c,s in R:
        if re.search(p,d):
            # vasos/plantas só saem de Decoração/Outros; o resto só reclassifica "Outros" ou itens de jardinagem
            if c=='Jardinagem' or cat=='Outros': return c,s
    return cat,sub
